using System;
using System.Collections;
using System.IO;
using Gxdl;
using UnityEditor;
using UnityEngine;
public static class GxdlPlayCheck {
 [MenuItem("GXDL/QA/Export Build Report")] public static void Report(){var r=UnityEditor.Build.Reporting.BuildReport.GetLatestReport();if(r==null)throw new Exception("No build report");var s=r.summary;var messages=new System.Collections.Generic.List<string>();foreach(var step in r.steps)foreach(var message in step.messages)if(message.type==LogType.Warning)messages.Add(message.content);File.WriteAllText("Logs/gxdl-build.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{result=s.result.ToString(),errors=s.totalErrors,warnings=s.totalWarnings,warningMessages=messages,bytes=s.totalSize,path=s.outputPath,seconds=s.totalTime.TotalSeconds},Newtonsoft.Json.Formatting.Indented));}
 [MenuItem("GXDL/QA/Home")] public static void Home(){GxdlGame.Instance.Home();}
 [MenuItem("GXDL/QA/Chop")] public static void Chop(){GxdlGame.Instance.CloseModal();GxdlGame.Instance.Chop();}
 [MenuItem("GXDL/QA/Replace")] public static void Replace(){GxdlGame.Instance.ResolveDrop(true);}
 [MenuItem("GXDL/QA/Skins")] public static void Skins(){GxdlGame.Instance.Skins();}
 [MenuItem("GXDL/QA/Battle")] public static void Battle(){GxdlGame.Instance.CloseModal();GxdlGame.Instance.StartBattle();}
 [MenuItem("GXDL/QA/Smoke Test")] public static void Smoke(){GxdlGame.Instance.StartCoroutine(Check());}
 [MenuItem("GXDL/QA/Victory Test")] public static void Victory(){GxdlGame.Instance.StartCoroutine(CheckVictory());}
 [MenuItem("GXDL/QA/Effects Test")] public static void Effects(){GxdlGame.Instance.StartCoroutine(CheckEffects());}
 static IEnumerator CheckEffects(){var g=GxdlGame.Instance;var backup=Newtonsoft.Json.JsonConvert.SerializeObject(g.Rules.Save);try{
 g.Home();if(g.Rules.Save.pending!=null)g.ResolveDrop(false);int peaches=g.Rules.Save.peaches;g.Chop();g.Chop();yield return new WaitForSeconds(.4f);ScreenCapture.CaptureScreenshot("Assets/Screenshots/gxdl-chop-feedback.png");yield return new WaitForSeconds(.75f);
 if(g.Rules.Save.peaches!=peaches-1||g.Rules.Save.pending==null)throw new Exception("Repeated chop consumed extra peaches");
 g.ResolveDrop(true);yield return new WaitForSeconds(.15f);ScreenCapture.CaptureScreenshot("Assets/Screenshots/gxdl-equip-feedback.png");yield return new WaitForSeconds(1.6f);
 g.StartBattle();g.ToggleBattleSpeed();foreach(var a in UnityEngine.Object.FindObjectsOfType<OriginalAnimation>())if(a.Speed!=2)throw new Exception("Battle animation speed mismatch");
 yield return new WaitForSeconds(.32f);ScreenCapture.CaptureScreenshot("Assets/Screenshots/gxdl-hit-feedback.png");yield return new WaitForEndOfFrame();yield return null;g.Home();int stage=g.Rules.Save.stage;yield return new WaitForSeconds(2);
 if(g.Rules.Save.stage!=stage)throw new Exception("Cancelled fight changed stage");
 g.ToggleBattleSpeed();g.ToggleBattleSpeed();
 File.WriteAllText("Logs/gxdl-effects-test.txt","PASS: repeated chop guard, impact/experience and equipment effects, animation speed x2, cancelled battle, save restored. "+DateTime.Now.ToString("O"));
 }finally{g.Rules.Save=Newtonsoft.Json.JsonConvert.DeserializeObject<SaveData>(backup);g.Rules.Store();g.Home();}}
 [MenuItem("GXDL/QA/Stone Trajectory Test")] public static void Trajectory(){float rise=60,drop=45,total=SpiritStoneMotion.Duration(rise,drop);var origin=SpiritStoneMotion.Sample(0,90,rise,drop);var peak=SpiritStoneMotion.Sample(rise/300,90,rise,drop);var land=SpiritStoneMotion.Sample((2*rise+drop)/300,90,rise,drop);var bounce=SpiritStoneMotion.Sample((2*rise+drop+.7f*drop)/300,90,rise,drop);var end=SpiritStoneMotion.Sample(total+.01f,90,rise,drop);File.WriteAllText("Logs/gxdl-trajectory-values.txt",$"origin={origin} peak={peak} land={land} bounce={bounce} end={end}");if(origin!=Vector2.zero||Mathf.Abs(peak.y-rise)>.1f||Mathf.Abs(land.y+drop)>.1f||Mathf.Abs(bounce.y+drop*.5f)>.1f||(end-new Vector2(90,-drop)).sqrMagnitude>.001f)throw new Exception("Stone trajectory phases mismatch");File.WriteAllText("Logs/gxdl-trajectory-test.txt","PASS: rise, accelerated fall, half-height bounce, ground endpoint; source GoodsFallingEffect.js; video 44.3-45.6s.");}
 [MenuItem("GXDL/QA/Disassemble Test")] public static void Disassemble(){GxdlGame.Instance.StartCoroutine(CheckDisassemble());}
 static IEnumerator CheckDisassemble(){var g=GxdlGame.Instance;string backup=Newtonsoft.Json.JsonConvert.SerializeObject(g.Rules.Save);try{g.Home();g.Rules.Save.pending=null;g.Rules.Save.peaches=Math.Max(1,g.Rules.Save.peaches);g.Home();g.Chop();yield return new WaitForSeconds(1.1f);g.Rules.Save.pending.quality=3;g.Home();int before=g.Rules.Save.coins;var gearBefore=Newtonsoft.Json.JsonConvert.SerializeObject(g.Rules.Save.gear);UnityEngine.UI.Button button=null;foreach(var b in UnityEngine.Object.FindObjectsOfType<UnityEngine.UI.Button>())if(b.name=="Resolve Equipment")button=b;if(button==null)throw new Exception("Missing disassemble button");button.onClick.Invoke();button.onClick.Invoke();if(g.Rules.Save.coins!=before+60||g.Rules.Save.pending!=null)throw new Exception("Disassemble reward or duplicate settlement failed");if(Newtonsoft.Json.JsonConvert.SerializeObject(g.Rules.Save.gear)!=gearBefore)throw new Exception("Disassemble changed equipped gear");
 yield return new WaitForSeconds(.3f);int drops=0;foreach(var im in UnityEngine.Object.FindObjectsOfType<UnityEngine.UI.Image>())if(im.name=="Spirit Stone Drop")drops++;if(drops!=10)throw new Exception("Missing falling stones");ScreenCapture.CaptureScreenshot("Assets/Screenshots/gxdl-disassemble-drop.png");yield return new WaitForSeconds(1.7f);UnityEngine.UI.Text balance=null;foreach(var t in UnityEngine.Object.FindObjectsOfType<UnityEngine.UI.Text>())if(t.name=="Spirit Stone Balance")balance=t;if(balance==null||balance.text!="灵石 "+(before+60))throw new Exception("HUD balance mismatch");if(GameRules.ReadSave().coins!=before+60)throw new Exception("Saved balance mismatch");ScreenCapture.CaptureScreenshot("Assets/Screenshots/gxdl-disassemble-collected.png");yield return new WaitForEndOfFrame();yield return null;
 int cuts=g.Rules.Save.cuts;g.Rules.Save.peaches=Math.Max(10,g.Rules.Save.peaches);foreach(var b in UnityEngine.Object.FindObjectsOfType<UnityEngine.UI.Button>()){var t=b.GetComponentInChildren<UnityEngine.UI.Text>();if(t!=null&&t.text=="自动砍树"){b.onClick.Invoke();break;}}yield return new WaitForSeconds(5.5f);if(g.Rules.Save.cuts<cuts+2)throw new Exception("Auto chop stopped after reward animation");g.Home();foreach(var b in UnityEngine.Object.FindObjectsOfType<UnityEngine.UI.Button>()){var t=b.GetComponentInChildren<UnityEngine.UI.Text>();if(t!=null&&t.text=="停止自动"){b.onClick.Invoke();break;}}
 File.WriteAllText("Logs/gxdl-disassemble-test.txt",$"PASS {DateTime.Now:O}: actual button clicked twice; reward exactly once; gear unchanged; 10 falling stones; balance {before} -> {before+60}; HUD and persisted save match; auto chop continued for at least two cycles.");
 }finally{g.Rules.Save=Newtonsoft.Json.JsonConvert.DeserializeObject<SaveData>(backup);g.Rules.Store();g.Home();}}
 static IEnumerator CheckVictory(){var g=GxdlGame.Instance;var backup=Newtonsoft.Json.JsonConvert.SerializeObject(g.Rules.Save);int stage=g.Rules.Save.stage;try{g.Home();g.Rules.Save.gear[0].attack+=100000;g.StartBattle();yield return new WaitForSeconds(8);if(g.Rules.Save.stage!=stage+1)throw new Exception("Victory did not advance stage");File.WriteAllText("Logs/gxdl-victory-test.txt","PASS: battle victory advances stage and grants configured rewards.");Debug.Log("[GXDL TEST] Victory passed.");}finally{g.Rules.Save=Newtonsoft.Json.JsonConvert.DeserializeObject<SaveData>(backup);g.Rules.Store();g.Home();}}
 static IEnumerator Check(){var g=GxdlGame.Instance;g.Home();if(g.Rules.Save.pending!=null)g.ResolveDrop(false);int before=g.Rules.Save.peaches;g.Chop();yield return new WaitForSeconds(1.2f);if(g.Rules.Save.pending==null||g.Rules.Save.peaches!=before-1)throw new Exception("Chop UI failed");g.ResolveDrop(true);yield return new WaitForSeconds(1.6f);if(g.Rules.Save.pending!=null)throw new Exception("Replace UI failed");g.Skins();yield return null;g.Home();g.Rules.Store();var read=GameRules.ReadSave();if(read==null||read.peaches!=g.Rules.Save.peaches)throw new Exception("Persistence failed");File.WriteAllText("Logs/gxdl-smoke-test.txt","PASS: chop, pending drop, replacement, skins, return home, persisted save.");Debug.Log("[GXDL TEST] Play-mode smoke passed.");}
}
